pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a non-payable target contract
        NonPayableTarget target = new NonPayableTarget();

        // Fund owner
        vm.deal(address(this), 2 ether);

        // Owner sends 2 ether to c via fallback to set depositsCount > 0
        vm.prank(address(this));
        (bool success,) = address(c).call{value: 2 ether}("");
        require(success, "initial deposit failed");

        // Now c has 2 ether and depositsCount == 1

        // Owner calls sendMoney to send 1 ether to non-payable target
        // This will cause a deposit via fallback, but target has no receive ether function
        bool ok;
        vm.prank(address(this));
        try c.sendMoney(address(target), 1 ether, "") {
            ok = true;
        } catch {
            ok = false;
        }
        // sendMoney succeeds in both versions (low-level call doesn't revert)
        assertTrue(ok, "sendMoney should not revert");

        // Now test withdrawAll:
        // Reference: transfer reverts if send fails (non-payable target)
        // Buggy: send returns false, but no revert
        bool withdrawOk;
        vm.prank(address(this));
        try c.withdrawAll() {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        // The reference C reverts, so withdrawOk == false
        // The buggy M does not revert, so withdrawOk == true
        // We assert that testing the bug (i.e., we expect the original behavior to be false)
        assertTrue(!withdrawOk, "Reference: withdrawAll should revert; bug would not");
    }
}

contract NonPayableTarget {
    // No receive ether function - so send fails
    fallback() external payable {
        revert("non-payable");
    }
}

